DO $s17$
DECLARE p jsonb; q jsonb; e jsonb; cd text; lid int; n int:=0; b_leg jsonb; b_bridge jsonb; b_pub jsonb; b_dep jsonb; b_judge jsonb; b_cand int;
BEGIN
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO b_leg FROM lf_ops.reglas t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY legacy_id,nucleo_codigo,version_nucleo) INTO b_bridge FROM lf_ops.lf_nucleo_cobertura_legada t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_pub FROM lf_ops.nucleo_regla_versiones t WHERE estado='PUBLICADA';
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO b_judge FROM lf_ops.nucleo_juicios t;
 SELECT count(*) INTO b_cand FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA';
 IF EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla LIKE 'S17-C%') THEN RAISE EXCEPTION 'S17_CANDIDATES_ALREADY_EXIST'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements($packets$[{"tipo":"NUEVA","codigo":"S17-C01","clave":"s17_b2b_rule_security_baseline_001","familia":"SECURITY","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"B2B","modo":"HEREDA","dueno":"TECNICO","titulo":"Baseline seguridad login B2B","descripcion":"BLOQUEAR certificación del Login B2B sin evidencia de controles contra agotamiento de recursos y DDoS, inyección mediante validación server-side y consultas parametrizadas, XSS, SSRF, clickjacking, CORS, TLS y headers, replay, supply chain/SBOM y límites de payload. No afirmar implementación ni QA aprobada sin evidencia.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s17c01_login_b2b"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s17c01_certificacion_baseline"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s17c01_control_seguridad_sin_evidencia"},"der":{"lit":true}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c01_login_b2b":false,"s17c01_certificacion_baseline":false,"s17c01_control_seguridad_sin_evidencia":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c01_login_b2b":false,"s17c01_certificacion_baseline":false,"s17c01_control_seguridad_sin_evidencia":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c01_login_b2b":false,"s17c01_certificacion_baseline":true,"s17c01_control_seguridad_sin_evidencia":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c01_login_b2b":false,"s17c01_certificacion_baseline":true,"s17c01_control_seguridad_sin_evidencia":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c01_login_b2b":true,"s17c01_certificacion_baseline":false,"s17c01_control_seguridad_sin_evidencia":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c01_login_b2b":true,"s17c01_certificacion_baseline":false,"s17c01_control_seguridad_sin_evidencia":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c01_login_b2b":true,"s17c01_certificacion_baseline":true,"s17c01_control_seguridad_sin_evidencia":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s17c01_login_b2b":true,"s17c01_certificacion_baseline":true,"s17c01_control_seguridad_sin_evidencia":true},"esperado":true}],"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/657","solicitante":"Cristhian / Claude S17 2026-11-24"}},{"tipo":"NUEVA","codigo":"S17-C02","clave":"s17_reg_client_home_installment_plan_modal_001","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"TECNICO","titulo":"Borrador de selección de plan en modal","descripcion":"BLOQUEAR modal de cuotas que preseleccione plan nuevo, habilite Aplicar sin plan válido, persista cambios antes de Aplicar o altere selección comprometida al cancelar o cerrar. Solo restaurar plan previo de misma oferta, versión y vigencia; aplicar revalidación backend y actualizar únicamente oferta contextual y resumen, sin cálculo monetario frontend.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s17c02_modal_plan_cuotas"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s17c02_interaccion_seleccion"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s17c02_borrador_o_commit_invalido"},"der":{"lit":true}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c02_modal_plan_cuotas":false,"s17c02_interaccion_seleccion":false,"s17c02_borrador_o_commit_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c02_modal_plan_cuotas":false,"s17c02_interaccion_seleccion":false,"s17c02_borrador_o_commit_invalido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c02_modal_plan_cuotas":false,"s17c02_interaccion_seleccion":true,"s17c02_borrador_o_commit_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c02_modal_plan_cuotas":false,"s17c02_interaccion_seleccion":true,"s17c02_borrador_o_commit_invalido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c02_modal_plan_cuotas":true,"s17c02_interaccion_seleccion":false,"s17c02_borrador_o_commit_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c02_modal_plan_cuotas":true,"s17c02_interaccion_seleccion":false,"s17c02_borrador_o_commit_invalido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c02_modal_plan_cuotas":true,"s17c02_interaccion_seleccion":true,"s17c02_borrador_o_commit_invalido":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s17c02_modal_plan_cuotas":true,"s17c02_interaccion_seleccion":true,"s17c02_borrador_o_commit_invalido":true},"esperado":true}],"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/559","solicitante":"Cristhian / Claude S17 2026-11-24"}},{"tipo":"NUEVA","codigo":"S17-C03","clave":"s17_ux_respaldo_no_compite_01","familia":"DESIGN_SYSTEM","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"TECNICO","titulo":"Respaldo sin competir con acción principal","descripcion":"BLOQUEAR bloque de confianza de Home que desplace jerarquía del Hero, Ruta de Claridad o CTA principal, incluya CTA del simulador o agregue panel explicativo sin evidencia real.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s17c03_home_publico"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s17c03_bloque_respaldo_presentado"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s17c03_jerarquia_o_cta_invalido"},"der":{"lit":true}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c03_home_publico":false,"s17c03_bloque_respaldo_presentado":false,"s17c03_jerarquia_o_cta_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c03_home_publico":false,"s17c03_bloque_respaldo_presentado":false,"s17c03_jerarquia_o_cta_invalido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c03_home_publico":false,"s17c03_bloque_respaldo_presentado":true,"s17c03_jerarquia_o_cta_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c03_home_publico":false,"s17c03_bloque_respaldo_presentado":true,"s17c03_jerarquia_o_cta_invalido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c03_home_publico":true,"s17c03_bloque_respaldo_presentado":false,"s17c03_jerarquia_o_cta_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c03_home_publico":true,"s17c03_bloque_respaldo_presentado":false,"s17c03_jerarquia_o_cta_invalido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c03_home_publico":true,"s17c03_bloque_respaldo_presentado":true,"s17c03_jerarquia_o_cta_invalido":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s17c03_home_publico":true,"s17c03_bloque_respaldo_presentado":true,"s17c03_jerarquia_o_cta_invalido":true},"esperado":true}],"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/369","solicitante":"Cristhian / Claude S17 2026-11-24"}},{"tipo":"NUEVA","codigo":"S17-C04","clave":"s17_ux_token_consolidacion_02","familia":"DESIGN_SYSTEM","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"TECNICO","titulo":"Token de contraste reutilizable Home","descripcion":"BLOQUEAR restricción de slate_text_strong exclusivamente al Hero cuando un subtítulo, disclaimer o microcopy de Home requiera margen de contraste; usar token canónico sin copiar hex ni fijar nuevas métricas.","condicion":{"op":"y","izq":{"op":"y","izq":{"op":"=","izq":{"hecho":"s17c04_home"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s17c04_microcopy_requiere_contraste"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s17c04_token_restringido_indebidamente"},"der":{"lit":true}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c04_home":false,"s17c04_microcopy_requiere_contraste":false,"s17c04_token_restringido_indebidamente":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c04_home":false,"s17c04_microcopy_requiere_contraste":false,"s17c04_token_restringido_indebidamente":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c04_home":false,"s17c04_microcopy_requiere_contraste":true,"s17c04_token_restringido_indebidamente":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c04_home":false,"s17c04_microcopy_requiere_contraste":true,"s17c04_token_restringido_indebidamente":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c04_home":true,"s17c04_microcopy_requiere_contraste":false,"s17c04_token_restringido_indebidamente":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c04_home":true,"s17c04_microcopy_requiere_contraste":false,"s17c04_token_restringido_indebidamente":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s17c04_home":true,"s17c04_microcopy_requiere_contraste":true,"s17c04_token_restringido_indebidamente":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s17c04_home":true,"s17c04_microcopy_requiere_contraste":true,"s17c04_token_restringido_indebidamente":true},"esperado":true}],"efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/361","solicitante":"Cristhian / Claude S17 2026-11-24"}}]$packets$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=substring(p->'origen'->>'ref' from '[0-9]+$')::int;
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND NOT EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid AND estado='VIGENTE' AND NOT coalesce(pendiente_decision,false)) THEN RAISE EXCEPTION 'S17_SOURCE_NOT_ELIGIBLE %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S17_ALREADY_COVERED %',lid; END IF;
 q:=lf_ops.nucleo_regla_proponer_v1(p,false);
 IF q->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (q->>'bloqueantes')::int<>0 THEN RAISE EXCEPTION 'S17_PREFLIGHT_FAIL % %',cd,q; END IF;
 q:=lf_ops.nucleo_regla_proponer_v1(p,true);
 IF q->>'resultado'<>'CANDIDATA' OR (q->>'version')::int<>1 THEN RAISE EXCEPTION 'S17_CREATE_FAIL % %',cd,q; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 OR (SELECT count(distinct entrada::text) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 THEN RAISE EXCEPTION 'S17_VECTOR_INVALID %',cd; END IF;
 e:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF e->>'decision'<>'BLOQUEADA' OR e->>'hash_paquete' IS NULL THEN RAISE EXCEPTION 'S17_GATE_FAIL % %',cd,e; END IF;
 n:=n+1; RAISE NOTICE 'S17_CANDIDATE % hash=%',cd,e->>'hash_paquete';
 END LOOP;
 IF n<>4 OR (SELECT count(*) FROM lf_ops.nucleo_regla_versiones WHERE estado='CANDIDATA')<>b_cand+4 OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla LIKE 'S17-C%')<>32
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada t) IS DISTINCT FROM b_bridge
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones t WHERE estado='PUBLICADA') IS DISTINCT FROM b_pub
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep
 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.nucleo_juicios t) IS DISTINCT FROM b_judge THEN RAISE EXCEPTION 'S17_CONSERVATION_FAIL'; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.pantallas WHERE id=36) AND jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S17_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S17_PASS 4 CANDIDATAS 32 VECTORES 0 PROMOCIONES';
END $s17$;
COMMIT;
